$admin=$p->query("SELECT u.userid,u.ativo,u.senha_usa_hash,p.codigo perfil,p.acesso_total FROM usuarios u LEFT JOIN perfis p ON p.codperfil=u.codperfil WHERE u.userid='admin'")->fetch();
