$s=$p->prepare("INSERT INTO registros_migracao (codigo_migracao,origem,destino,tipo,versao,status,quantidade_registros,iniciada_em,concluida_em,detalhes) VALUES ('ATLAS_LOGIN_HOMOLOGACAO','GreenPortal HTTP + gatlas_dbp','ATLAS/gatlas_dbp','HOMOLOGACAO','0.160.0','CONCLUIDA',1,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,?) ON DUPLICATE KEY UPDATE status='CONCLUIDA',quantidade_registros=1,concluida_em=CURRENT_TIMESTAMP,detalhes=VALUES(detalhes)");$s->execute([json_encode($detail,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)]);echo json_encode($detail,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE).PHP_EOL;
